// Client wrapper over the vendored WASM rules engine (DECISIONS.md D1):
// the producer's `atomic-movegen` 2.3 compiled to wasm32-unknown-unknown,
// glue generated by wasm-bindgen (see engine/build.sh).
//
// Usage: `const engine = await loadEngine()` once; the returned facade is
// synchronous from then on. Board ids come from `new(fen)` and must be
// released with `free(id)`; `apply`/`undo` maintain a DFS-friendly undo
// stack inside the engine (one do_move per edge, one undo per backtrack).
import init, {
  engine_new,
  engine_free,
  engine_apply,
  engine_undo,
  engine_fen,
  engine_hash,
  engine_terminal,
  engine_outcome,
  engine_legal,
  engine_uci,
} from '../vendor/engine/atomic_solver_engine.js';

let readyPromise = null;

function ready() {
  if (!readyPromise) {
    readyPromise = init().catch((err) => {
      readyPromise = null;
      throw new Error(
        `rules engine failed to load (${err?.message ?? err}). ` +
          'Was it built and vendored? Run: sh engine/build.sh'
      );
    });
  }
  return readyPromise;
}

// Initialise the WASM module and return the synchronous facade used by the
// replay gate (and later, board navigation).
export async function loadEngine() {
  await ready();
  return {
    new: engine_new, // fen -> boardId (throws on invalid FEN)
    free: engine_free, // boardId -> ()
    apply: engine_apply, // boardId x move_code -> ()
    undo: engine_undo, // boardId x move_code -> ()
    fen: engine_fen, // boardId -> string
    hash: engine_hash, // boardId -> BigInt
    terminal: engine_terminal, // boardId -> bool
    outcome: engine_outcome, // boardId -> 'win'|'loss'|'draw'|null
    legal: engine_legal, // boardId -> move_code[]
    uci: engine_uci, // boardId x move_code -> 'e2e4'
  };
}
